_MD_NB_LINK_RE = re.compile(r"\[[^\]]*\]\(([^)#\s]+\.ipynb)(?:#[^)]*)?\)")

def _collect_project_refs(g: ProjectGraph) -> tuple[set, set, dict]:
    "Return `(all_code_refs, test_or_lesson_refs, class_members)` across notebooks and handwritten `.py`."
    all_refs, test_refs, cls_members = set(), set(), defaultdict(set)
    def _scan_tree(tree: ast.Module, is_test_scope: bool):
        for node in tree.body:
            if isinstance(node, ast.ClassDef):
                for item in node.body:
                    if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)): cls_members[node.name].add(item.name)
                    elif isinstance(item, ast.AnnAssign) and isinstance(item.target, ast.Name): cls_members[node.name].add(item.target.id)
                    elif isinstance(item, ast.Assign):
                        for t in item.targets:
                            if isinstance(t, ast.Name): cls_members[node.name].add(t.id)
        for node in ast.walk(tree):
            if isinstance(node, ast.Name):
                all_refs.add(node.id)
                if is_test_scope: test_refs.add(node.id)
            elif isinstance(node, ast.Attribute):
                all_refs.add(node.attr)
                if is_test_scope: test_refs.add(node.attr)
    for mod in g.modules.values():
        p = Path(mod.abs_path)
        if not p.is_file(): continue
        if p.suffix == ".ipynb":
            for cell in read_nb(p).cells:
                if cell.get("cell_type") != "code": continue
                tree, _ = parse_cell_ast(cell)
                if tree is not None: _scan_tree(tree, not is_exported(cell))
        elif p.suffix == ".py":
            try: tree = ast.parse(p.read_text(encoding="utf-8", errors="replace"))
            except SyntaxError: continue
            _scan_tree(tree, mod.role == "test")
    for s in g.symbols.values():
        if s.kind == "patch" and s.receiver: cls_members[s.receiver].add(s.name)
    return all_refs, test_refs, cls_members

def _exercised_symbols(g: ProjectGraph, test_refs: set) -> set[str]:
    "Return symbol UIDs exercised directly in lessons/tests or transitively via resolved calls."
    fwd = defaultdict(set)
    for e in g.edges:
        if e.kind in ("calls", "delegates", "patches", "tests") and e.confidence != "ambiguous": fwd[e.src].add(e.dst)
    exercised = {s.uid for s in g.symbols.values() if s.name in test_refs}
    exercised.update(e.dst for e in g.edges if e.kind == "tests" and e.confidence != "ambiguous")
    stack = list(exercised)
    while stack:
        cur = stack.pop()
        for nxt in fwd.get(cur, ()):
            if nxt not in exercised:
                exercised.add(nxt)
                stack.append(nxt)
    return exercised

