def _stale_doc_problems(g: ProjectGraph, root: Path, cls_members: dict) -> list[Diagnostic]:
    problems, seen = [], set()
    known_mods = set(g.mod_to_nodes) | ({g.package} if g.package else set())
    known_syms = {s.name for s in g.symbols.values()} | {s.qualname for s in g.symbols.values()}
    known_classes = {s.name for s in g.symbols.values() if s.kind == "class"}
    for rel, mod in g.modules.items():
        if not rel.endswith(".ipynb"): continue
        p = Path(mod.abs_path)
        if not p.is_file(): continue
        nb = read_nb(p)
        ch_map = _chapter_map(nb)
        for idx, cell in enumerate(nb.cells):
            if cell.get("cell_type") != "markdown": continue
            src, ch = cell_source(cell), ch_map.get(idx, "")
            for target in _MD_NB_LINK_RE.findall(src):
                if target.startswith(("http://", "https://")) or (p.parent / target).is_file() or (root / target).is_file(): continue
                key = (rel, str(cell.get("id", "")), target)
                if key not in seen:
                    seen.add(key)
                    problems.append(_diag("stale-doc-ref", "architecture", rel, f"Markdown link points to missing notebook `{target}`", cell=cell, chapter=ch, hint="Update or remove the broken notebook link"))
        for ref, cid, ch in g.doc_refs.get(rel, ()):
            key = (rel, cid, ref)
            if key in seen: continue
            if g.package and ref.startswith(g.package + "."):
                parts = ref.split(".")
                parent_mod = ".".join(parts[:-1])
                valid = ref in known_mods or parts[-1] == "_modidx" or (parent_mod in g.mod_exports and parts[-1] in g.mod_exports[parent_mod])
                if not valid:
                    seen.add(key)
                    problems.append(Diagnostic("stale-doc-ref", "architecture", "warning", rel,
                        f"Prose references unknown `{ref}`", cid, ch, 0, "Verify the module or symbol name against the project graph"))
            elif "." in ref:
                head, attr = ref.split(".", 1)
                if "." not in attr and head in known_classes and attr not in cls_members.get(head, ()) and not attr.startswith("__") and attr not in known_syms:
                    seen.add(key)
                    problems.append(Diagnostic("stale-doc-ref", "architecture", "warning", rel,
                        f"Prose references `{ref}` but `{head}` defines no `{attr}` member", cid, ch, 0, "Update documentation to match current class attributes/methods"))
    return problems

# %% ../nbs/04_review.ipynb #37aad987
def _architecture_problems(g: ProjectGraph, root: Path, *, check_orphans: bool = True) -> list[Diagnostic]:
    problems = []
    for cyc in g.cycles:
        problems.append(_diag("import-cycle", "architecture", cyc[0], f"Circular module import detected: {' -> '.join(cyc + [cyc[0]])}", severity="error", hint="Extract shared primitives into a lower-layer notebook"))
    by_mod_sym = defaultdict(list)
    for s in g.symbols.values():
        if s.module and s.node_id.endswith(".ipynb"): by_mod_sym[(s.module, s.qualname)].append(s)
    for (mod, qn), defs in sorted(by_mod_sym.items()):
        if len(defs) > 1:
            locs = ", ".join(f"{d.node_id}#{d.cell_id}" for d in defs)
            problems.append(Diagnostic("duplicate-export", "architecture", "error", defs[1].node_id,
                f"`{qn}` is exported multiple times into `{mod}` ({locs})", defs[1].cell_id, defs[1].chapter, defs[1].lineno, "Keep one canonical exported definition per symbol"))
    if check_orphans and g.package and (root / g.package).is_dir():
        for py_path in generated_py_paths(root / g.package):
            owner_ref = generated_owner_ref(py_path)
            if owner_ref is not None and not owner_ref.is_file():
                problems.append(_diag("orphan-generated-py", "architecture", _rel(py_path, root),
                    f"Generated module `{py_path.name}` points to missing notebook `{owner_ref.name}`", hint="Remove the stale generated module or restore its source notebook"))
    for src, _, reason in g.surprising:
        if reason.startswith("layer inversion"):
            problems.append(_diag("layer-inversion", "architecture", src, reason, hint="Keep lower-numbered notebooks free of dependencies on higher-numbered ones"))
    all_refs, test_refs, cls_members = _collect_project_refs(g)
    exercised = _exercised_symbols(g, test_refs)
    for s in g.symbols.values():
        if not s.node_id.endswith(".ipynb") or not s.module: continue
        if s.visibility in ("private", "exporti") and not s.name.startswith("__") and s.name not in all_refs:
            problems.append(Diagnostic("dead-internal-export", "architecture", "warning", s.node_id,
                f"Internal exported symbol `{s.qualname}` has no references anywhere in the project", s.cell_id, s.chapter, s.lineno, "Remove unused internal helper or inline it"))
        elif s.visibility == "public" and s.kind != "class" and s.uid not in exercised:
            problems.append(Diagnostic("untested-public-symbol", "architecture", "warning", s.node_id,
                f"Public symbol `{s.qualname}` is not exercised in any notebook lesson or test file", s.cell_id, s.chapter, s.lineno, "Exercise the symbol in a chapter lesson or `tests/`"))
    patch_nbs = defaultdict(set)
    for s in g.symbols.values():
        if s.kind == "patch" and s.receiver and s.node_id.endswith(".ipynb"): patch_nbs[s.receiver].add(s.node_id)
    for cls_name, nbs in sorted(patch_nbs.items()):
        if len(nbs) >= 3:
            problems.append(_diag("scattered-patch", "architecture", sorted(nbs)[0],
                f"Class `{cls_name}` is `@patch`-extended across {len(nbs)} notebooks ({', '.join(sorted(Path(n).name for n in nbs))})", hint="Document the full class API or consolidate closely related patches"))
    return problems + _stale_doc_problems(g, root, cls_members)

# %% ../nbs/04_review.ipynb #3e10706d
_CELL_ID_TAG_RE = re.compile(r":cell\[([^\]]+)\]$")

def _split_hint(text: str) -> tuple[str, str]:
    if " (hint: " in text and text.endswith(")"):
        msg, hint = text.rsplit(" (hint: ", 1)
        return msg.strip(), hint[:-1].strip()
    return text.strip(), ""

def _run_chkstyle(nb_path: Path, rel: str, ch_map: dict[int, str], id_to_idx: dict[str, int]) -> list[Diagnostic]:
    try: from chkstyle import core as chk_core
    except ModuleNotFoundError: return []
    found = []
    for cell_path, lineno, rule, raw_msg, _ in chk_core.check_notebook(str(nb_path)):
        m = _CELL_ID_TAG_RE.search(cell_path)
        cid = m.group(1) if m else ""
        msg, hint = _split_hint(raw_msg)
        ch = ch_map.get(id_to_idx.get(cid, -1), "")
        found.append(Diagnostic(rule, "style", "warning", rel, msg, cid, ch, int(lineno or 0), hint, "chkstyle"))
    return found

# %% ../nbs/04_review.ipynb #d8ecc1c5
def review_nb(
    path: str | Path = ".",  # Notebook or directory to review
    *,
    include_style: bool = True,  # Include `chkstyle` code and baseline narrative findings
    include_arch: bool = True,  # Include project-wide architecture and concept checks
) -> ReviewReport:
    "Run structural, state, narrative, architecture, and optional `chkstyle` diagnostics on notebooks under `path`."
    p = Path(path).expanduser()
    root = project_root(p)
    diags, metrics = [], {}
    graph = nb_graph(p) if include_arch else None
    known_exports = {m: set(syms) for m, syms in graph.mod_exports.items()} if graph else None
    multi_owner = {m for m, nbs in graph.mod_to_nodes.items() if len(nbs) > 1} if graph else None
    for nb_path in notebook_paths(p):
        nb = read_nb(nb_path)
        rel = _rel(nb_path, root)
        ch_map = _chapter_map(nb)
        id_to_idx = {str(c.get("id", "")): i for i, c in enumerate(nb.cells)}
        diags.extend(_structure_problems(nb_path, nb, rel, ch_map, multi_owner_mods=multi_owner))
        diags.extend(_state_problems(nb, rel, ch_map, known_exports=known_exports))
        diags.extend(_narrative_problems(nb, rel, ch_map))
        if include_style: diags.extend(_run_chkstyle(nb_path, rel, ch_map, id_to_idx))
        code_n = sum(c.get("cell_type") == "code" for c in nb.cells)
        hide_n = sum(c.get("cell_type") == "code" and is_hidden(c) for c in nb.cells)
        metrics[rel] = dict(cells=len(nb.cells), code=code_n, hidden=hide_n, hidden_pct=round(100 * hide_n / code_n) if code_n else 0)
    if graph is not None and p.is_dir(): diags.extend(_architecture_problems(graph, root))
    return ReviewReport(str(p), diags, metrics)

def check_nb(
    path: str | Path = ".",  # Notebook or directory to check
    *,
    include_style: bool = True,  # Include `chkstyle` findings
    include_arch: bool = True,  # Include project-wide architecture and concept checks
    strict: bool = False,  # Raise `RuntimeError` if any finding exists
) -> int:
    "Print a compact review report and return `0` when clean or `1` when findings exist."
    report = review_nb(path, include_style=include_style, include_arch=include_arch)
    print(report)
    if strict and report.diagnostics: raise RuntimeError(str(report))
    return 1 if report.diagnostics else 0
